20	func cmdEvidenceImportTerminalBench(args []string) int {
21		fs := flagSet("evidence import-terminalbench")
22		workDir := fs.String("work-dir", "", "Repository root (default: cwd)")
23		matrixDir := fs.String("matrix", "", "TerminalBench matrix output directory")
24		outPath := fs.String("out", "", "Output JSONL path")
25		if err := fs.Parse(args); err != nil {
26			return 2
27		}
28		if strings.TrimSpace(*matrixDir) == "" || strings.TrimSpace(*outPath) == "" {
29			fmt.Fprintf(os.Stderr, "Usage: %s evidence import-terminalbench --matrix <dir> --out <records.jsonl>\n", benchCommandName())
30			return 2
31		}
32	
33		wd := resolveWorkDir(*workDir)
34		matrixRoot := resolveMatrixPath(wd, *matrixDir)
35		outFile := resolveMatrixPath(wd, *outPath)
36	
37		matrixOut, err := loadTerminalBenchMatrixOutput(matrixRoot)
38		if err != nil {
39			fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: load matrix: %v\n", benchCommandName(), err)
40			return 1
41		}
42	
43		metadata, _ := loadTerminalBenchMatrixMetadata(matrixRoot)
44		subsetPath := resolveBenchmarkPath(wd, matrixRoot, matrixOut.SubsetPath)
45		subset, err := loadTermbenchSubset(subsetPath)
46		if err != nil {
47			fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: load subset %s: %v\n", benchCommandName(), subsetPath, err)
48			return 1
49		}
50	
51		records := make([]map[string]any, 0, len(matrixOut.Runs))
52		if len(matrixOut.Runs) > 0 {
53			for _, run := range matrixOut.Runs {
54				record, err := buildTerminalBenchRecord(wd, matrixRoot, matrixOut, subset, metadata, run)
55				if err != nil {
56					fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: %v\n", benchCommandName(), err)
57					return 1
58				}
59				records = append(records, record)
60			}
61		} else if len(matrixOut.Cells) > 0 {
62			for _, cell := range matrixOut.Cells {
63				record, err := buildTerminalBenchAggregateRecord(matrixRoot, matrixOut, subset, metadata, cell)
64				if err != nil {
65					fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: %v\n", benchCommandName(), err)
66					return 1
67				}
68				records = append(records, record)
69			}
70		} else {
71			fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: matrix.json contains no runs or cells\n", benchCommandName())
72			return 1
73		}
74	
75		if err := os.MkdirAll(filepath.Dir(outFile), 0o750); err != nil {
76			fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: create output dir: %v\n", benchCommandName(), err)
77			return 1
78		}
79		tmp, err := os.CreateTemp(filepath.Dir(outFile), filepath.Base(outFile)+".*.tmp")
80		if err != nil {
81			fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: create temp output: %v\n", benchCommandName(), err)
82			return 1
83		}
84		tmpName := tmp.Name()
85		writeErr := writeBenchmarkEvidenceJSONL(tmp, records)
86		closeErr := tmp.Close()
87		if writeErr == nil {
88			writeErr = closeErr
89		}
90		if writeErr != nil {
91			_ = os.Remove(tmpName)
92			fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: write output: %v\n", benchCommandName(), writeErr)
93			return 1
94		}
95	
96		validator, err := evidence.NewValidator(wd)
97		if err != nil {
98			_ = os.Remove(tmpName)
99			fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: %v\n", benchCommandName(), err)
100			return 1
101		}
102		if _, err := validator.ValidateFile(tmpName); err != nil {
103			_ = os.Remove(tmpName)
104			fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: validate output: %v\n", benchCommandName(), err)
105			return 1
106		}
107		if err := os.Rename(tmpName, outFile); err != nil {
108			_ = os.Remove(tmpName)
109			fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: rename output: %v\n", benchCommandName(), err)
110			return 1
111		}
112	
113		fmt.Fprintf(os.Stderr, "%s evidence import-terminalbench: imported %d record(s) to %s\n", benchCommandName(), len(records), outFile)
114		return 0
115	}
