117	func loadTerminalBenchMatrixOutput(matrixRoot string) (*matrixOutput, error) {
118		raw, err := os.ReadFile(filepath.Join(matrixRoot, "matrix.json"))
119		if err != nil {
120			return nil, fmt.Errorf("read matrix.json: %w", err)
121		}
122		var out matrixOutput
123		if err := json.Unmarshal(raw, &out); err != nil {
124			return nil, fmt.Errorf("parse matrix.json: %w", err)
125		}
126		return &out, nil
127	}
128	
129	func loadTerminalBenchMatrixMetadata(matrixRoot string) (map[string]any, error) {
130		path := filepath.Join(matrixRoot, terminalBenchMatrixMetadataName)
131		raw, err := os.ReadFile(path)
132		if err != nil {
133			if os.IsNotExist(err) {
134				return nil, nil
135			}
136			return nil, fmt.Errorf("read %s: %w", path, err)
137		}
138		var doc map[string]any
139		if err := json.Unmarshal(raw, &doc); err != nil {
140			return nil, fmt.Errorf("parse %s: %w", path, err)
141		}
142		return doc, nil
143	}
144	
145	func buildTerminalBenchRecord(workDir, matrixRoot string, matrix *matrixOutput, subset *termbenchSubset, metadata map[string]any, run matrixRunReport) (map[string]any, error) {
146		profilePath := resolveBenchmarkPath(workDir, matrixRoot, run.ProfilePath)
147		prof, err := profile.Load(profilePath)
148		if err != nil {
149			return nil, fmt.Errorf("load profile %s: %w", profilePath, err)
150		}
151	
152		record := terminalBenchBaseRecord(matrixRoot, matrix, subset, metadata, run, prof)
153		record["source"] = terminalBenchSourceRecord(matrixRoot, "matrix.json", run.OutputDir)
154		record["score"] = terminalBenchScoreRecord(run, 0)
155		record["final_status"] = run.FinalStatus
156		if invalidClass := classifyMatrixInvalid(run); invalidClass != "" {
157			record["invalid_class"] = invalidClass
158			record["scope"].(map[string]any)["denominator_rule"] = "exclude_invalid_runs"
159			record["denominator"] = terminalBenchDenominatorRecord(run, invalidClass, false)
160			record["coverage"] = terminalBenchCoverageRecord(matrix, subset, metadata, run, invalidClass, false)
161		} else {
162			record["scope"].(map[string]any)["denominator_rule"] = "count_valid_tasks"
163			record["denominator"] = terminalBenchDenominatorRecord(run, "", true)
164			record["coverage"] = terminalBenchCoverageRecord(matrix, subset, metadata, run, "", true)
165		}
166	
167		if path, hash := terminalBenchArtifactHash(matrixRoot, run.OutputDir, "logs", "agent", "session.log.jsonl"); path != "" {
168			record["provenance"].(map[string]any)["session_log_path"] = path
169			record["provenance"].(map[string]any)["session_log_sha256"] = hash
170		}
171		if path, hash := terminalBenchArtifactHash(matrixRoot, run.OutputDir, "logs", "agent", "trajectory.json"); path != "" {
172			record["provenance"].(map[string]any)["trajectory_path"] = path
173			record["provenance"].(map[string]any)["trajectory_sha256"] = hash
174		}
175		if path, hash := terminalBenchArtifactHash(matrixRoot, run.OutputDir, "logs", "verifier", "reward.txt"); path != "" {
176			record["components"].(map[string]any)["reward_file_path"] = path
177			record["components"].(map[string]any)["reward_file_sha256"] = hash
178		}
179	
180		if run.Reward == nil {
181			if reward, err := terminalBenchRewardFromFile(matrixRoot, run.OutputDir); err == nil {
182				record["score"] = terminalBenchScoreRecord(run, reward)
183			}
184		}
185		if run.Reward != nil {
186			record["score"] = terminalBenchScoreRecord(run, *run.Reward)
187		}
188	
189		if err := terminalBenchApplyMetadata(record, metadata, prof, run); err != nil {
190			return nil, err
191		}
192	
193		recordID, err := evidence.StableRecordID(record)
194		if err != nil {
195			return nil, err
196		}
197		record["record_id"] = recordID
198		return record, nil
199	}
