14	// CorpusTask is a single benchmark task loaded from a YAML or JSON file in the
15	// corpus directory.
16	type CorpusTask struct {
17		ID            string   `yaml:"id"            json:"id"`
18		Description   string   `yaml:"description"   json:"description"`
19		Prompt        string   `yaml:"prompt"        json:"prompt"`
20		ExpectedTools []string `yaml:"expected_tools" json:"expected_tools,omitempty"`
21		Permissions   string   `yaml:"permissions"   json:"permissions,omitempty"`
22		Reasoning     string   `yaml:"reasoning"     json:"reasoning,omitempty"`
23		Tags          []string `yaml:"tags"          json:"tags,omitempty"`
24	}
25	
26	// loadCorpus reads all *.yaml / *.yml / *.json files from dir and returns
27	// the parsed tasks in filename order.
28	func loadCorpus(dir string) ([]CorpusTask, error) {
29		entries, err := os.ReadDir(dir)
30		if err != nil {
31			return nil, fmt.Errorf("read corpus dir %s: %w", dir, err)
32		}
33	
34		var tasks []CorpusTask
35		for _, e := range entries {
36			if e.IsDir() {
37				continue
38			}
39			name := e.Name()
40			if !strings.HasSuffix(name, ".yaml") &&
41				!strings.HasSuffix(name, ".yml") &&
42				!strings.HasSuffix(name, ".json") {
43				continue
44			}
45			path := filepath.Join(dir, name)
46			data, err := safefs.ReadFile(path)
47			if err != nil {
48				return nil, fmt.Errorf("read %s: %w", path, err)
49			}
50			var t CorpusTask
51			if strings.HasSuffix(name, ".json") {
52				if err := json.Unmarshal(data, &t); err != nil {
53					return nil, fmt.Errorf("parse %s: %w", path, err)
54				}
55			} else {
56				if err := yaml.Unmarshal(data, &t); err != nil {
57					return nil, fmt.Errorf("parse %s: %w", path, err)
58				}
59			}
60			if t.ID == "" {
61				t.ID = strings.TrimSuffix(name, filepath.Ext(name))
62			}
63			tasks = append(tasks, t)
64		}
65		return tasks, nil
66	}
