48	func TestMatrixResumeSkipsTerminalReport(t *testing.T) {
49		repoRoot := benchRepoRoot(t)
50		outDir := t.TempDir()
51	
52		args := []string{
53			"--work-dir", repoRoot,
54			"--harnesses", "dumb_script",
55			"--profiles", "noop",
56			"--reps", "1",
57			"--out", outDir,
58		}
59		if code := cmdMatrix(args); code != 0 {
60			t.Fatalf("initial cmdMatrix exit = %d, want 0", code)
61		}
62	
63		reportPath := filepath.Join(outDir, "cells", "dumb_script", "noop", "rep-001", "fix-git", matrixReportName)
64		before, err := os.Stat(reportPath)
65		if err != nil {
66			t.Fatalf("stat report: %v", err)
67		}
68		time.Sleep(20 * time.Millisecond)
69		if code := cmdMatrix(append(args, "--resume")); code != 0 {
70			t.Fatalf("resume cmdMatrix exit = %d, want 0", code)
71		}
72		after, err := os.Stat(reportPath)
73		if err != nil {
74			t.Fatalf("stat report after resume: %v", err)
75		}
76		if !after.ModTime().Equal(before.ModTime()) {
77			t.Fatalf("terminal report was rewritten on resume: before=%s after=%s", before.ModTime(), after.ModTime())
78		}
79	}
