129		raw, _ := json.Marshal(lock)
130		if err := os.WriteFile(lockPath, raw, 0o600); err != nil {
131			t.Fatal(err)
132		}
133		if code := cmdMatrix(append(args, "--out", resumeOut, "--resume")); code != 0 {
134			t.Fatalf("resume cmdMatrix exit = %d, want 0", code)
135		}
136	
137		clean := readMatrixOutput(t, filepath.Join(cleanOut, "matrix.json"))
138		resumed := readMatrixOutput(t, filepath.Join(resumeOut, "matrix.json"))
139		if len(clean.Runs) != len(resumed.Runs) {
140			t.Fatalf("resumed run count = %d, want %d", len(resumed.Runs), len(clean.Runs))
141		}
142		for i := range clean.Runs {
143			if clean.Runs[i].Harness != resumed.Runs[i].Harness ||
144				clean.Runs[i].ProfileID != resumed.Runs[i].ProfileID ||
145				clean.Runs[i].Rep != resumed.Runs[i].Rep ||
146				clean.Runs[i].TaskID != resumed.Runs[i].TaskID ||
147				clean.Runs[i].FinalStatus != resumed.Runs[i].FinalStatus {
148				t.Fatalf("resumed run[%d] mismatch:\nclean=%+v\nresumed=%+v", i, clean.Runs[i], resumed.Runs[i])
149			}
150			if clean.Runs[i].Reward == nil && resumed.Runs[i].Reward != nil ||
151				clean.Runs[i].Reward != nil && resumed.Runs[i].Reward == nil ||
152				clean.Runs[i].Reward != nil && resumed.Runs[i].Reward != nil && *clean.Runs[i].Reward != *resumed.Runs[i].Reward {
153				t.Fatalf("resumed reward[%d] mismatch", i)
154			}
155		}
156	}
