308	func runSweepPhase(opts sweepRunOpts, phase sweepPhase) int {
309		reps := phase.Reps
310		if reps == 0 {
311			reps = opts.plan.Defaults.Reps
312		}
313		subsetPath := sweepResolveSubsetPath(opts.wd, phase.Subset)
314	
315		// Per-resource-group semaphores to enforce max_concurrency.
316		rgSems := map[string]chan struct{}{}
317		for _, rg := range opts.plan.ResourceGroups {
318			cap := rg.MaxConcurrency
319			if cap < 1 {
320				cap = 1
321			}
322			rgSems[rg.ID] = make(chan struct{}, cap)
323		}
324	
325		type laneOutcome struct {
326			laneID string
327			code   int
328			meta   sweepLaneMeta
329			matrix *matrixOutput
330		}
331		outcomes := make([]laneOutcome, len(phase.Lanes))
332	
333		var wg sync.WaitGroup
334		for i, laneID := range phase.Lanes {
335			lane, ok := opts.laneByID[laneID]
336			if !ok {
337				fmt.Fprintf(os.Stderr, "%s sweep: lane %q not found in plan\n", benchCommandName(), laneID)
338				return 1
339			}
340			rg, ok := opts.rgByID[lane.ResourceGroup]
341			if !ok {
342				fmt.Fprintf(os.Stderr, "%s sweep: resource group %q not found for lane %s\n", benchCommandName(), lane.ResourceGroup, laneID)
343				return 1
344			}
345			sem := rgSems[rg.ID]
346			if sem == nil {
347				sem = make(chan struct{}, 1)
348				rgSems[rg.ID] = sem
349			}
350	
351			wg.Add(1)
352			go func(i int, lane *sweepLane, rg *sweepResourceGroup, sem chan struct{}) {
353				defer wg.Done()
354				sem <- struct{}{}
355				defer func() { <-sem }()
356	
357				laneOutDir := filepath.Join(opts.outDir, phase.ID, lane.ID)
358				jobs := 1
359				if rg.MaxConcurrency > 1 && opts.matrixJobsManaged > 1 {
360					jobs = opts.matrixJobsManaged
361				}
362				matrixArgs := buildSweepMatrixArgs(opts, phase, lane, rg, subsetPath, laneOutDir, reps)
363				if jobs > 1 {
364					matrixArgs = append(matrixArgs, "--jobs", fmt.Sprintf("%d", jobs))
365				}
366	
367				meta := buildSweepLaneMeta(opts, phase, lane, rg, subsetPath, laneOutDir, reps, matrixArgs)
368				if err := os.MkdirAll(laneOutDir, 0o750); err != nil {
369					fmt.Fprintf(os.Stderr, "%s sweep: mkdir lane out dir %s: %v\n", benchCommandName(), laneOutDir, err)
370					outcomes[i] = laneOutcome{laneID: lane.ID, code: 1, meta: meta}
371					return
372				}
373				if err := writeJSONAtomic(filepath.Join(laneOutDir, "sweep_lane_meta.json"), meta); err != nil {
374					fmt.Fprintf(os.Stderr, "%s sweep: write lane meta %s: %v\n", benchCommandName(), lane.ID, err)
375					outcomes[i] = laneOutcome{laneID: lane.ID, code: 1, meta: meta}
376					return
377				}
378	
379				fmt.Printf("[sweep] phase=%s lane=%s rg=%s (max_concurrency=%d) starting\n",

380					phase.ID, lane.ID, rg.ID, rg.MaxConcurrency)
381				code := cmdMatrix(matrixArgs)
382				fmt.Printf("[sweep] phase=%s lane=%s exit=%d\n", phase.ID, lane.ID, code)
383	
384				var mout *matrixOutput
385				matrixPath := filepath.Join(laneOutDir, "matrix.json")
386				if raw, err := os.ReadFile(matrixPath); err == nil { // #nosec G304 -- runner-owned output path
387					var mo matrixOutput
388					if json.Unmarshal(raw, &mo) == nil {
389						mout = &mo
390					}
391				}
392				outcomes[i] = laneOutcome{laneID: lane.ID, code: code, meta: meta, matrix: mout}
393			}(i, lane, rg, sem)
394		}
395		wg.Wait()
396	
397		// Print per-phase summary (AC-9).
398		printSweepPhaseSummary(phase.ID, outcomes)
399	
400		for _, o := range outcomes {
401			if o.code != 0 {
402				return o.code
403			}
404		}
405		return 0
406	}
