446	func summarizeSweepLane(laneID string, mout *matrixOutput) sweepSummaryRow {
447		row := sweepSummaryRow{LaneID: laneID}
448		if mout == nil {
449			return row
450		}
451		for _, run := range mout.Runs {
452			row.NRuns++
453			row.WallSeconds += floatVal(run.WallSeconds)
454			row.InputTokens += intValue(run.InputTokens)
455			row.OutputTokens += intValue(run.OutputTokens)
456			row.CachedTokens += intValue(run.CachedInputTokens)
457			row.CostUSD += run.CostUSD
458			if ic := classifyMatrixInvalid(run); ic != "" {
459				row.NInvalid++
460				if row.InvalidCounts == nil {
461					row.InvalidCounts = map[string]int{}
462				}
463				row.InvalidCounts[ic]++
464			} else {
465				row.NValid++
466				if run.Reward != nil && *run.Reward == 1 {
467					row.NPasses++
468				}
469			}
470		}
471		if row.NValid > 0 {
472			v := row.CostUSD / float64(row.NValid)
473			row.EffCostPerValid = &v
474		}
475		if row.NPasses > 0 {
476			v := row.CostUSD / float64(row.NPasses)
477			row.EffCostPerPass = &v
478		}
479		return row

480	}
