669	func sweepMatrixSummary(sweepOutDir string) ([]sweepSummaryRow, error) {
670		entries, err := os.ReadDir(sweepOutDir)
671		if err != nil {
672			return nil, err
673		}
674		var rows []sweepSummaryRow
675		for _, phaseEntry := range entries {
676			if !phaseEntry.IsDir() {
677				continue
678			}
679			phaseDir := filepath.Join(sweepOutDir, phaseEntry.Name())
680			laneEntries, err := os.ReadDir(phaseDir)
681			if err != nil {
682				continue
683			}
684			for _, laneEntry := range laneEntries {
685				if !laneEntry.IsDir() {
686					continue
687				}
688				matrixPath := filepath.Join(phaseDir, laneEntry.Name(), "matrix.json")
689				raw, err := os.ReadFile(matrixPath) // #nosec G304 -- runner-owned output path
690				if err != nil {
691					continue
692				}
693				var mout matrixOutput
694				if err := json.Unmarshal(raw, &mout); err != nil {
695					continue
696				}
697				row := summarizeSweepLane(laneEntry.Name(), &mout)
698				rows = append(rows, row)
699			}
700		}
701		sort.Slice(rows, func(i, j int) bool { return rows[i].LaneID < rows[j].LaneID })
702		return rows, nil
703	}
704	
705	// printSweepPhaseSummary is a private helper; the outer function with outcomes
706	// slice was already defined. This version accepts the outcome slice directly.
707	func printSweepPhaseSummary(phaseID string, outcomes []struct {
708		laneID string
709		code   int
710		meta   sweepLaneMeta
711		matrix *matrixOutput
712	}) {
713		_ = math.NaN() // ensure math import is used
714		fmt.Printf("\n=== Phase Summary: %s ===\n", phaseID)
715		hdr := fmt.Sprintf("%-42s %5s %5s %7s %10s %10s %10s %12s %14s %14s",
716			"Lane", "Pass", "Fail", "Invalid", "WallSec", "InToks", "OutToks", "Cost($)", "EffCost/Valid", "EffCost/Pass")
717		sep := strings.Repeat("-", len(hdr))
718		fmt.Println(hdr)
719		fmt.Println(sep)
720	
721		for _, o := range outcomes {
722			row := summarizeSweepLane(o.laneID, o.matrix)
723			effValid := "-"
724			effPass := "-"
725			if row.EffCostPerValid != nil {
726				effValid = fmt.Sprintf("$%.4f", *row.EffCostPerValid)
727			}
728			if row.EffCostPerPass != nil {
729				effPass = fmt.Sprintf("$%.4f", *row.EffCostPerPass)
730			}
731			fmt.Printf("%-42s %5d %5d %7d %10.1f %10d %10d %12.4f %14s %14s\n",
732				truncStr(o.laneID, 42),
733				row.NPasses,
734				row.NValid-row.NPasses,
735				row.NInvalid,
736				row.WallSeconds,
737				row.InputTokens,
738				row.OutputTokens,
739				row.CostUSD,
