// TestSelectSweepPhasesUnknownReturnsError verifies unknown phase IDs error.
func TestSelectSweepPhasesUnknownReturnsError(t *testing.T) {
	plan, err := loadSweepPlan(sweepPlanPath(t))
	if err != nil {
		t.Fatalf("loadSweepPlan: %v", err)
	}
