		resume:          true,
		forceRerun:      false,
		perRunBudgetUSD: 5.0,
		rgByID:          sweepRGMap(plan),
		laneByID:        sweepLaneMap(plan),
	}
	lane := opts.laneByID["fiz-openrouter-claude-sonnet-4-6"]
	rg := opts.rgByID[lane.ResourceGroup]
	phase := plan.Phases[0]
	subsetPath := sweepResolveSubsetPath(wd, phase.Subset)
